<?php
declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$user=$auth->requireUser();$message='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);try{$action=(string)($_POST['action']??'');if($action==='add')$emails->add((int)$user['id'],(string)$_POST['email']);elseif($action==='verify')$emails->sendVerification((int)$_POST['email_id'],(int)$user['id']);elseif($action==='primary')$emails->makePrimary((int)$_POST['email_id'],(int)$user['id']);elseif($action==='remove')$emails->remove((int)$_POST['email_id'],(int)$user['id']);$requiredActions->refreshAutomaticCompletions((int)$user['id']);$message='<div class="alert success">Operacja zakończona.</div>';}catch(Throwable $e){$message='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}
$rows='';foreach($emails->list((int)$user['id']) as $e){$rows.='<tr><td>'.Web::e($e['email']).'</td><td>'.($e['verified_at']?'Tak':'Nie').'</td><td>'.((bool)$e['is_primary']?'Podstawowy':'Dodatkowy').'</td><td><form class="inline" method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="email_id" value="'.(int)$e['id'].'">'.(!$e['verified_at']?'<button name="action" value="verify">Wyślij weryfikację</button>':'').(!$e['is_primary']&&$e['verified_at']?'<button name="action" value="primary">Ustaw podstawowy</button>':'').(!$e['is_primary']?'<button name="action" value="remove">Usuń</button>':'').'</form></td></tr>';}
Web::page('E-maile','<div class="page-head"><div><h1>Adresy e-mail</h1><p>Podstawowy i dodatkowe adresy używane również jako alias logowania.</p></div></div>'.$message.'<section class="card"><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Dodaj adres<input type="email" name="email" required></label><button name="action" value="add">Dodaj i zweryfikuj</button></form></section><div class="table-wrap"><table><thead><tr><th>E-mail</th><th>Zweryfikowany</th><th>Typ</th><th>Akcje</th></tr></thead><tbody>'.$rows.'</tbody></table></div>',$user);
